<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $member_id = absint( $args['member_id'] ); if ( ! is_user_logged_in() || ! function_exists( 'sd_core_connection_status' ) ) { return; } $status = sd_core_connection_status( $member_id ); $labels = array( 'is_friend' => 'Friends', 'pending' => 'Request sent', 'awaiting_response' => 'Accept request', 'not_friends' => 'Connect' ); $actions = array( 'is_friend' => 'remove', 'pending' => 'cancel', 'awaiting_response' => 'accept', 'not_friends' => 'connect' ); if ( ! isset( $labels[ $status ], $actions[ $status ] ) ) { return; } ?><button class="sd-button sd-button-outline sd-connection-button" type="button" data-sd-connection="<?php echo esc_attr( $member_id ); ?>" data-sd-connection-action="<?php echo esc_attr( $actions[ $status ] ); ?>"><?php echo esc_html( $labels[ $status ] ); ?></button>
